declare(strict_types=1);require __DIR__.'/common.php';try{$b=post_json();$name=text($b['name']??'',120);$email=email($b['email']??'');$phone=text($b['phone']??'',40);$subject=text($b['subject']??'Informazioni Workshop',160);$message=text($b['message']??'',2000);if($name===''||$message==='')out(['status'=>'error','message'=>'Campi obbligatori mancanti'],400);$content="Nome: {$name}\nEmail: {$email}\nTelefono: {$phone}\nOggetto: {$subject}\n\n{$message}";if(!mail_site(cfg('SMTP_FROM'),'Richiesta info — '.$subject,$content))throw new RuntimeException();out(['status'=>'ok','message'=>'Messaggio inviato']);}catch(Throwable){out(['status'=>'error','message'=>'Invio non riuscito'],500);}
